% Find simple directed routes with at most MaxStopovers intermediate airports.
% Example: path_discovery('Ostend-Bruges International Airport',
%                         'Václav Havel Airport Prague', 2, Path).
path_discovery(From, To, MaxStopovers, Path) :-
    integer(MaxStopovers), MaxStopovers >= 0,
    airport(Source, From), airport(Destination, To),
    Source \= Destination,
    route_airports(Source, Destination, MaxStopovers, [Source], Airports),
    airport_names(Airports, Path).

route_airports(From, To, _, Visited, [From, To]) :-
    flight(From, To), unvisited(To, Visited).
route_airports(From, To, Remaining, Visited, [From|Rest]) :-
    Remaining > 0,
    flight(From, Via), Via \= To, unvisited(Via, Visited),
    Next is Remaining-1,
    route_airports(Via, To, Next, [Via|Visited], Rest).

% Explicit disequalities make cycle prevention independently checkable.
unvisited(_, []).
unvisited(Airport, [Other|Rest]) :-
    Airport \= Other, unvisited(Airport, Rest).
airport_names([], []).
airport_names([Id|Ids], [Name|Names]) :-
    airport(Id, Name), airport_names(Ids, Names).

?- path_discovery('Ostend-Bruges International Airport', 'Václav Havel Airport Prague', 2, Path).
